id.bookPartResourceUrl@value@js:
var url = String(result);
if(url.indexOf('http') !== 0){ url = 'https://www.tadu.com' + url; }
var res = java.ajax(url);
try { 
    var text = JSON.parse(res).data.content;
    // 按换行或段落标签将正文切成一行行
    var arr = text.split(/(<br\s*\/?>|<\/?p>|\n)/i);
    var cleanArr = [];
    for(var i=0; i<arr.length; i++) {
        var line = arr[i];
        // 如果这一段话里同时包含了 塔、读、说 三个字，认定为广告并丢弃
        if (line.indexOf('塔') !== -1 && line.indexOf('读') !== -1 && line.indexOf('说') !== -1) {
            continue; 
        }
        cleanArr.push(line);
    }
    // 把干净的行重新拼装起来
    res = cleanArr.join('');
} catch(e) {}
res || '付费章节，换源阅读！'##【作者题外话】:(.*|\n)|书友群.*|【作者的话.*
